/* -----------------------------------------------------------------------
 * test_delete_confirm.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — Delete "Tap Again" Confirm Unit Tests
 *
 * Covers delete_confirm.c using the Unity test framework.
 * No hardware required — runs on any host PC via CMake.
 *
 * Times are tick counts in ms, as TonyTask passes them
 * (osKernelGetTickCount). T0 is the first tap.
 *
 * Test groups:
 *   Group A — Two taps: arm, confirm 0.5 to 3 s later, too soon, too late
 *   Group B — What disarms it: a timeout (also across the tick wrap), a
 *             new selection, cancel, the confirm itself
 *   Group C — Texts: the row label and the info-line prompt fit
 *   Group D — NULL and empty names
 * ----------------------------------------------------------------------- */

#include "unity.h"
#include <stdio.h>
#include <string.h>
#include "delete_confirm.h"

void setUp(void)   {}
void tearDown(void) {}

#define T0      100000U                 /* when the first tap comes */

/* Shared instances reused across tests */
static delete_confirm_t dc;
static char             armed[DC_NAME_LEN];

/* Helper — a fresh confirm, armed for name by a first tap at T0 */
static void arm(const char *name)
{
    dc_init(&dc);
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0, name, armed));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP A — Two taps
 * ═══════════════════════════════════════════════════════════════════════ */

void test_A01_the_first_tap_arms(void)
{
    dc_init(&dc);
    TEST_ASSERT_FALSE(dc_armed(&dc));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0, "REC05.WAV", armed));
    TEST_ASSERT_TRUE(dc_armed(&dc));
}

void test_A02_a_second_tap_from_500_ms_to_just_under_3_s_confirms(void)
{
    static const uint32_t after[] = { DC_MIN_MS, 501U, 1000U, 2000U, DC_CONFIRM_MS - 1U };

    for (size_t i = 0U; i < sizeof(after) / sizeof(after[0]); i++) {
        arm("REC05.WAV");
        TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED, dc_press(&dc, T0 + after[i], "REC05.WAV", armed));
    }
}

void test_A03_a_second_tap_under_500_ms_is_ignored_and_stays_armed(void)
{
    /* Rows 2 (Select) and 3 (Delete) are 2 px apart: a quick double tap,
     * or a tap meant for Select, must never delete. */
    arm("REC05.WAV");
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(&dc, T0 + 80U, "REC05.WAV", armed));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(&dc, T0 + DC_MIN_MS - 1U, "REC05.WAV", armed));
    TEST_ASSERT_TRUE(dc_armed(&dc));
    /* ... and the next tap in time still confirms, counted from the first */
    TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED, dc_press(&dc, T0 + 700U, "REC05.WAV", armed));
}

void test_A04_the_confirm_gives_the_armed_name(void)
{
    /* Raw bytes too: the name goes back to Jack as he listed it */
    char raw[DC_NAME_LEN];
    snprintf(raw, sizeof(raw), "R%cSUM.WAV", (char)0x82);
    arm(raw);
    memset(armed, 'x', sizeof(armed));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED, dc_press(&dc, T0 + 1000U, raw, armed));
    TEST_ASSERT_EQUAL_STRING(raw, armed);
}

void test_A05_a_tap_after_3_s_arms_again(void)
{
    /* The armed row timed out (and nothing called dc_update): a new
     * first tap, not a confirm */
    arm("REC05.WAV");
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0 + DC_CONFIRM_MS, "REC05.WAV", armed));
    TEST_ASSERT_TRUE(dc_armed(&dc));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(&dc, T0 + DC_CONFIRM_MS + 100U, "REC05.WAV", armed));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED,
                          dc_press(&dc, T0 + DC_CONFIRM_MS + DC_MIN_MS, "REC05.WAV", armed));
}

void test_A06_a_tap_for_another_name_arms_that_name(void)
{
    /* Only the name the screen showed at the first tap can be deleted */
    arm("REC05.WAV");
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0 + 1000U, "REC06.WAV", armed));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED, dc_press(&dc, T0 + 2000U, "REC06.WAV", armed));
    TEST_ASSERT_EQUAL_STRING("REC06.WAV", armed);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP B — What disarms it
 * ═══════════════════════════════════════════════════════════════════════ */

void test_B01_update_times_out_at_3_s(void)
{
    arm("REC05.WAV");
    TEST_ASSERT_FALSE(dc_update(&dc, T0 + DC_CONFIRM_MS - 1U));
    TEST_ASSERT_TRUE(dc_armed(&dc));
    TEST_ASSERT_TRUE(dc_update(&dc, T0 + DC_CONFIRM_MS));      /* timed out now */
    TEST_ASSERT_FALSE(dc_armed(&dc));
    TEST_ASSERT_FALSE(dc_update(&dc, T0 + DC_CONFIRM_MS + 1U)); /* once only */
}

void test_B02_the_timeout_works_across_the_tick_wrap(void)
{
    /* Armed 1 s before the 32-bit tick count wraps */
    const uint32_t t0 = 0xFFFFFFFFU - 999U;

    dc_init(&dc);
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, t0, "REC05.WAV", armed));
    TEST_ASSERT_FALSE(dc_update(&dc, 0xFFFFFFFFU));
    TEST_ASSERT_FALSE(dc_update(&dc, 1999U));                   /* 2999 ms after */
    TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED, dc_press(&dc, 500U, "REC05.WAV", armed));   /* 1500 ms after */

    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, t0, "REC05.WAV", armed));
    TEST_ASSERT_TRUE(dc_update(&dc, 2000U));                    /* 3000 ms after */
}

void test_B03_a_new_selection_disarms(void)
{
    arm("REC05.WAV");
    dc_name_changed(&dc, "REC05.WAV");              /* the same name: still armed */
    TEST_ASSERT_TRUE(dc_armed(&dc));
    dc_name_changed(&dc, "REC06.WAV");
    TEST_ASSERT_FALSE(dc_armed(&dc));

    arm("REC05.WAV");
    dc_name_changed(&dc, "");                       /* the card went: no selection */
    TEST_ASSERT_FALSE(dc_armed(&dc));
}

void test_B04_cancel_disarms(void)
{
    arm("REC05.WAV");
    dc_cancel(&dc);
    TEST_ASSERT_FALSE(dc_armed(&dc));
    /* The next tap is a first tap again */
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0 + 1000U, "REC05.WAV", armed));
}

void test_B05_a_confirmed_delete_disarms(void)
{
    arm("REC05.WAV");
    TEST_ASSERT_EQUAL_INT(DC_PRESS_CONFIRMED, dc_press(&dc, T0 + 1000U, "REC05.WAV", armed));
    TEST_ASSERT_FALSE(dc_armed(&dc));
    /* A third tap starts over: it can never delete twice */
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0 + 1600U, "REC05.WAV", armed));
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP C — Texts
 * ═══════════════════════════════════════════════════════════════════════ */

void test_C01_the_row_labels_fit_16_characters(void)
{
    dc_init(&dc);
    TEST_ASSERT_EQUAL_STRING("Delete", dc_label(&dc));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(DC_LABEL_MAX, strlen(dc_label(&dc)));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_ARMED, dc_press(&dc, T0, "REC05.WAV", armed));
    TEST_ASSERT_EQUAL_STRING("Sure? Tap again", dc_label(&dc));
    TEST_ASSERT_LESS_OR_EQUAL_UINT(DC_LABEL_MAX, strlen(dc_label(&dc)));
}

void test_C02_the_prompt_fits_20_characters(void)
{
    char prompt[32];

    dc_prompt("REC05.WAV", prompt, sizeof(prompt));
    TEST_ASSERT_EQUAL_STRING("Delete REC05.WAV?", prompt);
    dc_prompt("ABCDEFGH.WAV", prompt, sizeof(prompt));          /* the longest 8.3 name */
    TEST_ASSERT_EQUAL_STRING("Delete ABCDEFGH.WAV?", prompt);
    TEST_ASSERT_EQUAL_UINT(DC_PROMPT_MAX, strlen(prompt));
    dc_prompt("ABCDEFGHIJKLMNOP", prompt, sizeof(prompt));      /* never more than 12 of a name */
    TEST_ASSERT_EQUAL_STRING("Delete ABCDEFGHIJKL?", prompt);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP D — NULL and empty names
 * ═══════════════════════════════════════════════════════════════════════ */

void test_D01_an_empty_name_never_arms(void)
{
    dc_init(&dc);
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(&dc, T0, "", armed));
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(&dc, T0, NULL, armed));
    TEST_ASSERT_FALSE(dc_armed(&dc));
}

void test_D02_null_is_safe(void)
{
    char prompt[24];

    dc_init(NULL);
    dc_cancel(NULL);
    dc_name_changed(NULL, "A.WAV");
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(NULL, T0, "A.WAV", armed));
    TEST_ASSERT_FALSE(dc_update(NULL, T0));
    TEST_ASSERT_FALSE(dc_armed(NULL));
    TEST_ASSERT_EQUAL_STRING("Delete", dc_label(NULL));
    arm("A.WAV");                                   /* no place for the name: it is not confirmed */
    TEST_ASSERT_EQUAL_INT(DC_PRESS_IGNORED, dc_press(&dc, T0 + 1000U, "A.WAV", NULL));
    TEST_ASSERT_TRUE(dc_armed(&dc));
    dc_prompt(NULL, prompt, sizeof(prompt));
    TEST_ASSERT_EQUAL_STRING("Delete ?", prompt);
    dc_prompt("A.WAV", NULL, 8U);
}

/* ═══════════════════════════════════════════════════════════════════════
 * TEST RUNNER
 * ═══════════════════════════════════════════════════════════════════════ */

int main(void)
{
    UNITY_BEGIN();

    /* Group A — Two taps */
    RUN_TEST(test_A01_the_first_tap_arms);
    RUN_TEST(test_A02_a_second_tap_from_500_ms_to_just_under_3_s_confirms);
    RUN_TEST(test_A03_a_second_tap_under_500_ms_is_ignored_and_stays_armed);
    RUN_TEST(test_A04_the_confirm_gives_the_armed_name);
    RUN_TEST(test_A05_a_tap_after_3_s_arms_again);
    RUN_TEST(test_A06_a_tap_for_another_name_arms_that_name);

    /* Group B — What disarms it */
    RUN_TEST(test_B01_update_times_out_at_3_s);
    RUN_TEST(test_B02_the_timeout_works_across_the_tick_wrap);
    RUN_TEST(test_B03_a_new_selection_disarms);
    RUN_TEST(test_B04_cancel_disarms);
    RUN_TEST(test_B05_a_confirmed_delete_disarms);

    /* Group C — Texts */
    RUN_TEST(test_C01_the_row_labels_fit_16_characters);
    RUN_TEST(test_C02_the_prompt_fits_20_characters);

    /* Group D — NULL and empty names */
    RUN_TEST(test_D01_an_empty_name_never_arms);
    RUN_TEST(test_D02_null_is_safe);

    return UNITY_END();
}
